// Validate and enrich PostHog event
const items = $input.all();
const enriched = [];

for (const item of items) {
  const body = item.json.body || item.json;

  // PostHog webhook payload structure:
  // { distinct_id, event, properties: { $current_url, $city, $region, custom props... } }
  const event = body.event || body.properties?.$event_name;
  const distinctId = body.distinct_id || body.properties?.distinct_id;
  const props = body.properties || {};

  if (!event || !distinctId) continue;

  // Detect vertical from URL or properties
  const pageUrl = props.$current_url || props.page_url || '';
  let vertical = props.vertical || 'solar';
  if (pageUrl.includes('ev') || pageUrl.includes('mobilidade') || pageUrl.includes('wallbox')) {
    vertical = 'ev';
  }

  // Detect audience
  let audience = props.audience || 'b2c';
  if (pageUrl.includes('empresa') || pageUrl.includes('comercial') || pageUrl.includes('b2b')) {
    audience = 'b2b';
  }

  // Extract city from PostHog geo or custom property
  let city = props.city || props.$city;
  if (city) {
    const cityMap = {
      'florianopolis': 'Florianópolis', 'floripa': 'Florianópolis',
      'sao jose': 'São José', 'sao paulo': 'São Paulo',
      'bh': 'Belo Horizonte', 'belo horizonte': 'Belo Horizonte',
      'rio': 'Rio de Janeiro', 'rio de janeiro': 'Rio de Janeiro',
      'balneario camboriu': 'Balneário Camboriú', 'balneario': 'Balneário Camboriú'
    };
    const normalized = city.toLowerCase().trim();
    city = cityMap[normalized] || city;
  }

  // Extract state
  let state = props.state || props.$region;
  if (state && state.length > 2) {
    const stateMap = {
      'santa catarina': 'SC', 'sao paulo': 'SP', 'parana': 'PR',
      'rio grande do sul': 'RS', 'minas gerais': 'MG', 'rio de janeiro': 'RJ'
    };
    state = stateMap[state.toLowerCase()] || state.substring(0, 2).toUpperCase();
  }

  enriched.push({
    json: {
      event_name: event,
      user_session_id: String(distinctId),
      user_id: props.lead_id || props.user_id || null,
      page_url: pageUrl,
      city: city || null,
      state: state || null,
      company_id: props.company_id || null,
      category_id: props.category_id || null,
      vertical: vertical,
      audience: audience,
      utm_source: props.utm_source || null,
      utm_medium: props.utm_medium || null,
      utm_campaign: props.utm_campaign || null,
      utm_content: props.utm_content || null,
      referrer: props.$referrer || props.referrer || null,
      metadata: {
        browser: props.$browser,
        os: props.$os,
        device: props.$device_type,
        screen: props.$screen_height ? `${props.$screen_width}x${props.$screen_height}` : null,
        ...Object.fromEntries(
          Object.entries(props).filter(([k]) => 
            !k.startsWith('$') && !['utm_source','utm_medium','utm_campaign','utm_content','city','state','vertical','audience','lead_id','user_id','company_id','category_id','page_url','referrer'].includes(k)
          )
        )
      },
      created_at: body.timestamp || new Date().toISOString(),
      source: 'posthog_webhook'
    }
  });
}

return enriched;
